const q = $json.query ?? {};
const valid = q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === $vars.META_WEBHOOK_VERIFY_TOKEN;
return [{ json: { valid, challenge: valid ? q['hub.challenge'] : 'Forbidden', statusCode: valid ? 200 : 403 } }];

const signature = String($json.headers?.['x-hub-signature-256'] ?? '');
const raw = $json.rawBody ?? $json.bodyRaw ?? (typeof $json.body === 'string' ? $json.body : null);
if (!raw) throw new Error('Raw webhook body is required for signature verification');
if (!signature.startsWith('sha256=')) throw new Error('Missing Meta signature');
const enc = new TextEncoder();
const key = await crypto.subtle.importKey('raw', enc.encode($vars.META_APP_SECRET), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
const bytes = new Uint8Array(await crypto.subtle.sign('HMAC', key, enc.encode(raw)));
const expected = 'sha256=' + [...bytes].map((b) => b.toString(16).padStart(2, '0')).join('');
let mismatch = expected.length ^ signature.length;
for (let i = 0; i < Math.max(expected.length, signature.length); i++) mismatch |= (expected.charCodeAt(i) || 0) ^ (signature.charCodeAt(i) || 0);
if (mismatch !== 0) throw new Error('Invalid Meta signature');
const payload = JSON.parse(raw);
const events = [];
for (const entry of payload.entry ?? []) for (const change of entry.changes ?? []) {
  const v = change.value ?? {};
  if ((change.field === 'feed' && v.item === 'comment' && v.verb === 'add') || change.field === 'comments') events.push({ pageGraphId: String(entry.id), facebook_comment_id: String(v.comment_id ?? v.id), facebook_post_id: String(v.post_id ?? ''), facebook_user_id: v.from?.id ? String(v.from.id) : null, facebook_user_name: v.from?.name ?? null, message: v.message ?? '', parent_comment_id: v.parent_id ?? null, created_time: v.created_time ? new Date(Number(v.created_time) * 1000).toISOString() : null, metadata: v });
}
return events.filter((e) => e.facebook_comment_id && e.facebook_post_id).map((e) => ({ json: e }));

const event = $('Verify Signature and Normalize').item.json;
if (!$json.id) throw new Error('Unknown or disabled Facebook page');
return [{ json: { page_id: $json.id, facebook_comment_id: event.facebook_comment_id, facebook_post_id: event.facebook_post_id, facebook_user_id: event.facebook_user_id, facebook_user_name: event.facebook_user_name, message: event.message, parent_comment_id: event.parent_comment_id, created_time: event.created_time, metadata: event.metadata } }];
